#!/usr/bin/env bash
# Builds the app as a normal user: ./.venv with CPython 3.15 and the exact pins from requirements.txt.
set -euo pipefail
cd "$(dirname "$0")"
if [ -x /usr/local/bin/uv ]; then
  UV=/usr/local/bin/uv
  export UV_PYTHON_INSTALL_DIR=/opt/uv/python
else
  UV="$(command -v uv)"   # local development: uv on PATH
  "$UV" python install 3.15
fi
"$UV" venv --python 3.15 --managed-python --clear .venv
# Exact pins (generated by `uv pip compile requirements.in --universal --python-version 3.15`).
"$UV" pip sync --python .venv/bin/python --strict requirements.txt
.venv/bin/python -c 'import sys, fastapi, asyncpg; print("python build ok:", sys.version.split()[0], "fastapi", fastapi.__version__, "asyncpg", asyncpg.__version__)'
